import{c as o,Q as e,j as a,m as r}from"./chunks/framework.hhGiamYR.js";const h=JSON.parse('{"title":"爱情是一场需要胆量的战争--一个写了喜剧、情诗,还差点为邻家女子破产的政治家,如何看待爱、家庭与异性","description":"","frontmatter":{"date":"2026-08-17T00:00:00.000Z","title":"爱情是一场需要胆量的战争--一个写了喜剧、情诗,还差点为邻家女子破产的政治家,如何看待爱、家庭与异性"},"headers":[],"relativePath":"research/love-family/index.md","filePath":"research/love-family/index.md"}'),p={name:"research/love-family/index.md"};function n(s,t,l,i,c,d){return e(),a("div",null,[...t[0]||(t[0]=[r('<p>世人提起我,只记得国务秘书、史官、阴谋家这些头衔。他们忘了,我也写过《曼陀罗》那样的喜剧,写过《金驴记》那样的长诗,还在四十岁那年,为了一个邻家女子,把理智丢了个干干净净。</p><p>今天不谈王位继承,不谈雇佣军。谈爱情,谈家庭,谈男人女人之间那点亘古不变的角力。我这些看法,全都来自亲身经历——毕竟,一个既写过《曼陀罗》又写过《金驴记》的人,总不至于在情爱这事上说谎。</p><h2 id="一、爱情是一场战争-而战争需要算计" tabindex="-1">一、爱情是一场战争,而战争需要算计 <a class="header-anchor" href="#一、爱情是一场战争-而战争需要算计" aria-label="Permalink to &quot;一、爱情是一场战争,而战争需要算计&quot;">​</a></h2><p>《曼陀罗》里,青年卡利马科爱上了一位有夫之妇。他把自己关在屋里,独白里的煎熬,我至今觉得写得真切:</p><blockquote><p>📖 <strong>原文</strong>:《曼陀罗》第一幕,卡利马科独白</p><p>「这段时间以来,我的灵魂是备受煎熬!......我的希望越增加,我的惧怕就越见长。......我是条在两股对面风胁迫下的船,越驶近港口就越害怕。尼洽老爷的头脑简单给了我希望,卢克蕾佳的贞节坚定又让我害怕。」</p></blockquote><p>希望与恐惧,像两股相反的风,把人心这条船吹得团团转。这就是爱情的第一课:<strong>它从第一天起就是一场对抗</strong>。你对抗的或许是世俗、或许是情敌、或许只是对方的心防--但对抗始终存在。</p><p>年轻人总以为爱情是纯粹的天真烂漫。我劝你们把这场仗打明白。卡利马科赢下卢克蕾佳,靠的是什么?是他雇了食客李古潦,设计了整套骗局,连修士都买通了。整个过程像一场军事行动:侦察(打听尼洽老爷想要孩子)、布阵(借&quot;曼陀罗药酒&quot;之名)、总攻(趁夜潜入)。爱情的胜利,从来偏爱有准备的人。</p><h2 id="二、四十岁男人的狼狈-我和我的朋友都经历过" tabindex="-1">二、四十岁男人的狼狈，我和我的朋友都经历过 <a class="header-anchor" href="#二、四十岁男人的狼狈-我和我的朋友都经历过" aria-label="Permalink to &quot;二、四十岁男人的狼狈，我和我的朋友都经历过&quot;">​</a></h2><p>你们若觉得我把爱情说得太冷，那就听听我自己和朋友的坦白。1514年2月，我在佛罗伦萨给驻罗马的大使韦托里写信，顺嘴提到我的日常：</p><blockquote><p>📖 <strong>原文</strong>：《书信集》第229封，致韦托里，1514年2月4日</p><p>「我现在在佛罗伦萨，我把时间分成两半，一半在多纳托·德尔·科尔诺的店里度过，一半在里恰小姐那里度过……她叫我“家里的害虫”。不过他们都让我充当顾问，迄今为止，这个名头对我大有好处，多纳托让我在他的炉火旁暖身子，而她有时偷偷让我吻她。」</p></blockquote><p>“家里的害虫”——这是里恰小姐给我起的绰号。我一边给大使朋友写信谈公务，一边偷偷享受着小姐的吻。五天后，韦托里从罗马回信，倾诉了他的心事：</p><blockquote><p>📖 <strong>原文</strong>：《书信集》第230封，韦托里致我，1514年2月9日</p><p>「我四十岁了，我有一个妻子，而且有结了婚和已届适婚年龄的女儿，所以我没有任何东西可以随意抛弃。……第三天，她母亲晚上来和我说话，把女儿也带来了……屋里剩下我和她单独在炉火边。我忍不住和她聊天，抚摸她的手和脖子。她在我看来是多么美丽、多么讨人喜欢啊，我以前所下的一切决心早已抛到九霄云外了。」</p></blockquote><p>注意看这段自白的结构：先是清醒的盘算——年龄、妻女、家产、名声，全都在脑子里过了一遍；然后欲望登场，一夜之间，全部防线土崩瓦解。韦托里甚至自我开解，说“一个人意识到他的行为是错误的，就无须对他加以指责”。</p><p>你们以为这是软弱？我倒觉得，这正是我对爱情最诚实的观察：<strong>再清醒的头脑，也挡不住一个活生生的、美丽的人坐在你炉火边。</strong> 所以我不劝你们做苦行僧。我劝你们认清这个事实——欲望是人性的一部分，它来了，你要么驾驭它，要么被它驾驭。我的朋友在罗马选择投降，我在佛罗伦萨选择偷吻。两种都真实，也都狼狈。</p><h2 id="三、机运是女人-这句名言-你们理解反了" tabindex="-1">三、机运是女人--这句名言,你们理解反了 <a class="header-anchor" href="#三、机运是女人-这句名言-你们理解反了" aria-label="Permalink to &quot;三、机运是女人--这句名言,你们理解反了&quot;">​</a></h2><p>《君主论》第二十五章,我写过一句被后世嚼烂了的话:</p><blockquote><p>📖 <strong>原文</strong>:《君主论》第25章</p><p>「机运之神是一个女人,想要制服她,就必须打击她、压倒她。我们可以看到,她宁愿让大胆果敢的人而不是冷漠行事的人赢得。因此,同女人一样,机运始终是年轻人的朋友,因为他们不那么小心谨慎,却更加勇猛,能够更加大胆地支配她。」</p></blockquote><p>多少后人读到这里,骂我粗鄙、直男、物化女性。且慢。你们读懂了前半句,却漏了后半句--<strong>我是在说,机运偏爱年轻人,因为他们大胆</strong>。这句话的真正重量,落在&quot;大胆&quot;二字上。</p><p>我把机运比作女人,恰恰是因为在我那个时代,权势、财富、机遇,全都掌握在懂得主动出击的人手里。等待者坐失良机,勇猛者迎难而上。放在今天的情爱语境里,这句话依然成立:<strong>爱情与事业一样,偏爱敢出手的人。</strong> 你不表达,对方永远不会知道;你不争取,机会永远属于别人。所谓&quot;机运是女人的朋友&quot;--它同样是年轻人的朋友,只要你敢。</p><h2 id="四、家庭-我最后的堡垒" tabindex="-1">四、家庭:我最后的堡垒 <a class="header-anchor" href="#四、家庭-我最后的堡垒" aria-label="Permalink to &quot;四、家庭:我最后的堡垒&quot;">​</a></h2><p>你们也许好奇,这样一个浪荡子,如何看待家庭?</p><p>我一生颠沛,共和国倒台后丢了官,坐过牢,挨过吊刑。但我的妻子玛丽埃塔始终在家等我。我给她的信里,全是柴米油盐--卖柴的账目、孩子的功课、庄园的收成。没有一句情话,却句句是牵挂。乱世之中,家是我唯一没被夺走的东西。</p><blockquote><p>📖 <strong>原文</strong>:《书信集》致玛丽埃塔(选段)</p><p>「整个九月我就是这样度过的......早上我日出而作,然后去我正在让人砍伐的一片森林......离开小树林,我就去泉边,然后去几处我布置了鸟网的地方。我在胳膊下夹一本书,或是但丁的,或是彼特拉克的......」</p></blockquote><p>看见了吗?一个写《君主论》的人,给妻子的信里写的是砍柴、捕鸟、读书。<strong>大人物的小日子,才是他灵魂的底色。</strong> 爱情可以像战争一样需要算计,但家庭是那个让你卸下盔甲的地方。算计留给对手,温柔留给家人。这个次序,我建议年轻人记牢。</p><h2 id="五、给年轻人的三句话" tabindex="-1">五、给年轻人的三句话 <a class="header-anchor" href="#五、给年轻人的三句话" aria-label="Permalink to &quot;五、给年轻人的三句话&quot;">​</a></h2><p>第一,<strong>别把爱情神话化</strong>。它从来都是一场需要胆量、需要算计、也难免狼狈的战争。认清这一点,你反而能赢得更漂亮。</p><p>第二,<strong>欲望不丢人,被欲望牵着走才丢人</strong>。四十岁的我都挡不住炉火边的姑娘,你们二十多岁为情所困,实在不必自责。关键是在清醒的时候,给自己留一条退路。</p><p>第三,<strong>大胆是爱情里最稀缺的品质</strong>。机运偏爱年轻人,不是因为他们运气好,而是因为他们敢。敢表达、敢争取、敢承担结果--这三样,比任何情话都管用。</p><p>至于家庭?那是你打完全部战争之后,唯一确定会等你回去的地方。别把它弄丢了。</p><p>-- 尼科洛·马基雅维利,圣卡夏诺</p>',30)])])}const g=o(p,[["render",n]]);export{h as __pageData,g as default};
